import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ---------- Custom CUDA kernel source strings ----------

elementwise_add_kernel = """
__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}
"""

elementwise_add_cuda_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)


swish_kernel = """
__global__ void swish_elementwise_kernel(const float* a, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val_a = a[idx];
        float exp_val = expf(-val_a);
        float sigmoid_val = 1.0f / (1.0f + exp_val);
        out[idx] = val_a * sigmoid_val;
    }
}
"""

swish_cuda_source = (
    "torch::Tensor elementwise_swish_cuda(torch::Tensor x);"
)


# Load the custom CUDA functions via load_inline
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=(),
    cuda_sources=elementwise_add_cuda_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

swish = load_inline(
    name="elementwise_swish",
    cpp_sources=(),
    cuda_sources=swish_cuda_source,
    functions=["elementwise_swish_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)


class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.elementwise_add = elementwise_add  # placeholder, not used in forward
        self.swish = swish

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies Swish activation to the input tensor.
        Swish(x) = x * sigmoid(x)
        """
        return self.swish(x)
